\toprule
& \textbf{0v1} & \textbf{1v2} & \textbf{2v3} & \textbf{3v4} \\
\midrule
LightGBM  & .960 & .621 & .572 & .537 \\
DeBERTa   & .994 & .678 & .590 & .565 \\
\bottomrule
\end{tabular}
\end{minipage}

